<script lang="ts">const steps=['Not Started','Application Started','Application Submitted','Under Review','Documents Verification','Approved','Admission Confirmed'];</script><div class="max-w-3xl space-y-6"><div><h1 class="text-3xl font-bold text-white">Application Status</h1><p class="text-text-secondary mt-2">Review your application progress and required next actions.</p></div><section class="bg-card border border-white/10 rounded-2xl p-6"><div class="flex justify-between gap-4"><div><p class="text-xs uppercase tracking-wider text-accent">MCA · 2027 Intake</p><h2 class="text-xl text-white font-bold mt-2">Application in progress</h2></div><span class="text-sm text-accent bg-accent/15 px-3 py-2 h-fit rounded-full">Current stage</span></div><div class="mt-8 space-y-1">{#each steps as step,i}<div class="flex items-center gap-4"><span class:complete={i<2} class:active={i===2} class="progress-dot">{i<2?'✓':i+1}</span><p class:active-text={i===2} class="py-3 text-sm text-text-secondary">{step}</p></div>{/each}</div></section><section class="bg-card border border-white/10 rounded-2xl p-6 grid sm:grid-cols-3 gap-5"><div><p class="meta">Application Date</p><p class="text-white mt-1">—</p></div><div><p class="meta">Last Updated</p><p class="text-white mt-1">Today</p></div><div><p class="meta">Required Next Action</p><p class="text-accent mt-1">Complete application</p></div></section></div><style>.progress-dot{width:2rem;height:2rem;border-radius:999px;display:grid;place-items:center;background:rgba(255,255,255,.08);color:#a7a4b4}.progress-dot.complete{background:rgba(164,123,224,.35);color:#fff}.progress-dot.active{border:1px solid #a47be0;color:#a47be0}.active-text{color:#fff;font-weight:600}.meta{font-size:.7rem;text-transform:uppercase;letter-spacing:.1em;color:#a7a4b4}</style>
